fn ex(x: f64) -> String { format!("{:.180}", x).trim_end_matches('0').to_string() }
fn main(){
    let smallest_sub = f64::from_bits(0x36A0000000000000); // 2^-149
    println!("2^-149              = {}", ex(smallest_sub));
    let largest_sub = 8388607.0f64 * smallest_sub;
    println!("largest_sub (8388607*2^-149) = {}", ex(largest_sub));
    let fltmin = 8388608.0f64 * smallest_sub;
    println!("FLT_MIN = 2^-126    = {}", ex(fltmin));
    let mid_sub_min = 8388607.5f64 * smallest_sub;
    println!("mid(largest_sub,FLT_MIN) = {}", ex(mid_sub_min));
    let half_smallest = 0.5f64*smallest_sub;
    println!("2^-150 (mid 0,minsub)= {}", ex(half_smallest));
    println!("f32 of 2^-150 = {:e}", (half_smallest as f32));
    let fltmax = f32::MAX as f64;
    println!("FLT_MAX             = {}", ex(fltmax));
    let midinf = fltmax + (2f64.powi(104))/2.0; // ulp of FLT_MAX = 2^104
    println!("ulp(FLT_MAX)=2^104  = {}", ex(2f64.powi(104)));
    println!("mid(FLT_MAX,inf)    = {}", ex(midinf));
    // 1.0 neighbors
    let one = 1.0f64;
    let nx1 = (f32::from_bits(1f32.to_bits()+1)) as f64;
    let nx2 = (f32::from_bits(1f32.to_bits()+2)) as f64;
    println!("1.0 next            = {}", ex(nx1));
    println!("1.0 next2           = {}", ex(nx2));
    println!("mid(1,next)         = {}", ex((one+nx1)/2.0));
    println!("mid(next,next2)     = {}", ex((nx1+nx2)/2.0));
    // 1234565 family
    let a = 1234565.0f64; let b = 1234565.125f64;
    println!("mid(1234565,+ulp)   = {}", ex((a+b)/2.0));
    println!("1234565 as f32 g?   bits {:08x} {:08x}", 1234565.0f32.to_bits(), 1234565.125f32.to_bits());
}
EOF
